/* mqtt_handler.c - IoT device MQTT message processor */
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include "device_config.h"
#include "crypto_ops.h"

#define MAX_PAYLOAD_SIZE 4096
#define HEADER_SIZE 12

typedef struct {
    uint16_t msg_type;
    uint16_t flags;
    uint32_t payload_length;
    uint32_t sequence_num;
} __attribute__((packed)) msg_header_t;

typedef struct {
    uint8_t key_id[8];
    uint8_t iv[16];
    uint32_t ciphertext_len;
    uint8_t ciphertext[];
} __attribute__((packed)) encrypted_payload_t;

static uint8_t session_buffer[MAX_PAYLOAD_SIZE];
static uint32_t firmware_update_counter = 0;

/* Process incoming encrypted command from cloud backend */
int process_encrypted_command(const uint8_t *raw_msg, size_t raw_len) {
    if (raw_len < sizeof(msg_header_t)) {
        return -1;
    }

    msg_header_t *header = (msg_header_t *)raw_msg;

    /* Integer overflow vulnerability: payload_length is attacker-controlled uint32_t.
       Adding HEADER_SIZE can wrap around, bypassing the size check */
    uint32_t total_expected = header->payload_length + HEADER_SIZE;

    if (total_expected > MAX_PAYLOAD_SIZE) {
        return -1; /* Reject oversized messages */
    }

    if (raw_len < total_expected) {
        return -1;
    }

    /* Copy payload into session buffer - uses original payload_length which can be huge */
    const uint8_t *payload_start = raw_msg + HEADER_SIZE;
    memcpy(session_buffer, payload_start, header->payload_length); /* OVERFLOW */

    /* Parse as encrypted payload */
    encrypted_payload_t *enc = (encrypted_payload_t *)session_buffer;

    if (enc->ciphertext_len > MAX_PAYLOAD_SIZE - sizeof(encrypted_payload_t)) {
        return -1;
    }

    /* Decrypt using hardware crypto interface */
    uint8_t plaintext[MAX_PAYLOAD_SIZE];
    int decrypt_result = hw_crypto_decrypt(
        enc->key_id,
        enc->iv,
        enc->ciphertext,
        enc->ciphertext_len,
        plaintext
    );

    if (decrypt_result != 0) {
        return -2; /* Decryption failed */
    }

    /* Execute decrypted command */
    return execute_device_command(plaintext, enc->ciphertext_len);
}

/* Handle firmware update chunks */
int handle_firmware_chunk(const uint8_t *chunk, uint16_t chunk_count, uint16_t chunk_size) {
    /* Another potential overflow: chunk_count * chunk_size */
    uint32_t total_size = (uint32_t)chunk_count * (uint32_t)chunk_size;

    uint8_t *fw_buffer = malloc(total_size);
    if (!fw_buffer) return -1;

    /* Verify firmware signature before applying */
    int sig_valid = hw_crypto_verify_signature(
        chunk,
        total_size,
        NULL /* signature retrieved from secure element */
    );

    if (sig_valid != 1) {
        free(fw_buffer);
        return -3;
    }

    memcpy(fw_buffer, chunk, total_size);
    firmware_update_counter++;

    apply_firmware_update(fw_buffer, total_size);
    free(fw_buffer);
    return 0;
}

/* MQTT topic callback registration */
void register_mqtt_handlers(mqtt_client_t *client) {
    mqtt_subscribe(client, "device/cmd/encrypted", process_encrypted_command);
    mqtt_subscribe(client, "device/fw/chunk", handle_firmware_chunk);
    mqtt_subscribe(client, "device/diag/ping", handle_diagnostic_ping);
}
